import{_ as c,l,o,c as r,v as a,p as s,x as t,d,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"字符设备与 ioctl","description":"","frontmatter":{"title":"字符设备与 ioctl","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chardev-ioctl.md","filePath":"cs/chardev-ioctl.md","lastUpdated":1789023840000}'),_={name:"cs/chardev-ioctl.md"};function h(u,e,f,m,v,k){const i=l("Mermaid");return o(),r("div",null,[e[1]||(e[1]=a('<h1 id="字符设备与-ioctl" tabindex="-1">字符设备与 ioctl <a class="header-anchor" href="#字符设备与-ioctl" aria-label="Permalink to &quot;字符设备与 ioctl&quot;">​</a></h1><div class="epigraph"><p>字符设备用 file_operations 提供 read/write/poll；ioctl 用命令号逃出「字节流」无法表达的设备控制。</p><footer>—— 据 Linux ioctl 文档；LDD 对 cdev 的说明；[设备节点](/cs/device-nodes) 为先修</footer></div><p><a href="/cs/device-model-binding">设备模型</a> 的 probe 常注册 <strong>cdev</strong>。<a href="/cs/vfs">VFS</a> 把 fd 指到 fops。缺口是 ioctl 的 ABI：命令编码、拷贝、与 <a href="/cs/copy-from-user">copy_from_user</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>字节流不能「取硬件随机数熵统计」或「设波特率」。ioctl：<code>_IOW</code> 类宏编码方向与 magic。缺口：版本兼容；无类型检查导致内核读写用户；unlocked_ioctl。本课不把每个子系统的命令列出。</p><p><span class="marginnote">现代偏好 netlink、ioctl 减少、或 ioctl 经 bpf。对象仍是逃逸舱口。tun 已见过 fd 传包。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>open /dev/foo</code> → <code>unlocked_ioctl</code> → <code>copy_from_user</code> 结构 → 改硬件。对照 <a href="/cs/socket-options">setsockopt</a>：套接字的逃逸；ioctl 是文件的。对照 sysfs：属性文件更易脚本，不适合大二进制。对照 <a href="/cs/fuse">FUSE</a>：用户可实现 ioctl。</p>',8)),(o(),s(p,null,{default:t(()=>[n(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FD%5B%22cdev%20fd%22%5D%20--%3E%20IOCTL%5B%22ioctl%20cmd%22%5D%0A%20%20IOCTL%20--%3E%20COPY%5B%22copy_from_user%22%5D%0A%20%20COPY%20--%3E%20HW%5B%22%E9%A9%B1%E5%8A%A8%E4%B8%8E%E7%A1%AC%E4%BB%B6%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ioctl 让 Unix 文件抽象容纳设备个性，也是漏洞高发区。加固：copy 边界、cap 检查。不要写成 Windows DeviceIoControl 对照全文。与 <a href="/cs/kernel-audit">audit</a>：可监视特定 ioctl。</p><p>新接口优先避免 ioctl，但存量巨大。</p><p>实现上：命令号用 magic+序号+方向+大小编码，拷贝大小跟用户结构走，版本不对就内核读越界。unlocked_ioctl 不再持大内核锁，驱动自己串行化。 读法上只引用<a href="/cs/device-model-binding">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>字符设备与 ioctl</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 compat_ioctl 的全部 32/64。不保证图形 DRM 的命令缓冲。下一课用户态如何对 uevent 反应：udev。</p><p>版本字段会变，课序钉的是机制对象「字符设备与 ioctl」，不是某一主线内核的结构体名。 后课默认：设备控制可走 ioctl。热插事件与 udev 规则，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>cdev 用 fops；ioctl 传结构化命令。</li><li>必须经 copy_*_user 并做特权检查。</li><li>udev 热插是下一课。</li><li>出处：LDD；ioctl(2)；Linux API。</li></ul>',11))])}const A=c(_,[["render",h]]);export{b as __pageData,A as default};
